1	package com.loja.checkout.service;
2	
3	import com.loja.checkout.clube.NivelClube;
4	import com.loja.checkout.clube.NivelClubeRegistry;
5	import com.loja.checkout.cupom.Cupom;
6	import com.loja.checkout.cupom.CupomRegistry;
7	import com.loja.checkout.entrega.ModalidadeEntrega;
8	import com.loja.checkout.entrega.ModalidadeEntregaRegistry;
9	import com.loja.checkout.exception.CheckoutException;
10	import com.loja.checkout.exception.ErroCodigo;
11	import com.loja.checkout.model.ItemCarrinho;
12	import com.loja.checkout.model.PedidoRequest;
13	import com.loja.checkout.model.ResumoResponse;
14	import com.loja.checkout.pagamento.FormaPagamento;
15	import com.loja.checkout.pagamento.FormaPagamentoRegistry;
16	import com.loja.checkout.regiao.SeguroRegiao;
17	import org.springframework.stereotype.Service;
18	
19	import java.math.BigDecimal;
20	import java.math.RoundingMode;
21	import java.util.List;
22	
23	@Service
24	public class CheckoutService {
25	
26	    private final ModalidadeEntregaRegistry entregaRegistry;
27	    private final CupomRegistry cupomRegistry;
28	    private final NivelClubeRegistry clubeRegistry;
29	    private final FormaPagamentoRegistry pagamentoRegistry;
30	
31	    public CheckoutService(ModalidadeEntregaRegistry entregaRegistry,
32	                           CupomRegistry cupomRegistry,
33	                           NivelClubeRegistry clubeRegistry,
34	                           FormaPagamentoRegistry pagamentoRegistry) {
35	        this.entregaRegistry = entregaRegistry;
36	        this.cupomRegistry = cupomRegistry;
37	        this.clubeRegistry = clubeRegistry;
38	        this.pagamentoRegistry = pagamentoRegistry;
39	    }
40	
41	    public ResumoResponse calcular(PedidoRequest req) {
42	        // 1. Validate items
43	        validarItens(req.itens());
44	
45	        // 2. Validate nivel clube
46	        if (req.nivelClube() == null || clubeRegistry.buscar(req.nivelClube()) == null) {
47	            throw new CheckoutException(ErroCodigo.NIVEL_CLUBE_INVALIDO);
48	        }
49	        NivelClube nivelClube = clubeRegistry.buscar(req.nivelClube());
50	
51	        // 3. Validate regiao
52	        SeguroRegiao regiao = resolveRegiao(req.regiao());
53	
54	        // 4. Validate modalidade
55	        if (req.modalidadeEntrega() == null || entregaRegistry.buscar(req.modalidadeEntrega()) == null) {
56	            throw new CheckoutException(ErroCodigo.MODALIDADE_INVALIDA);
57	        }
58	        ModalidadeEntrega modalidade = entregaRegistry.buscar(req.modalidadeEntrega());
59	
60	        // 5. Validate modalidade disponibilidade
61	        double pesoTotal = calcularPesoTotal(req.itens());
62	        modalidade.validarDisponibilidade(pesoTotal);
63	
64	        // 6. Validate cupom exists (if provided)
65	        Cupom cupom = null;
66	        if (req.cupom() != null && !req.cupom().isBlank()) {
67	            cupom = cupomRegistry.buscar(req.cupom());
68	            if (cupom == null) {
69	                throw new CheckoutException(ErroCodigo.CUPOM_INVALIDO);
70	            }
71	        }
72	
73	        // Calculate subtotal before cupom validation
74	        BigDecimal subtotalProdutos = calcularSubtotal(req.itens());
75	
76	        // 7. Validate cupom aplicabilidade
77	        if (cupom != null) {
78	            cupom.validarAplicabilidade(subtotalProdutos);
79	        }
80	
81	        // 8. Validate forma pagamento
82	        if (req.formaPagamento() == null || pagamentoRegistry.buscar(req.formaPagamento()) == null) {
83	            throw new CheckoutException(ErroCodigo.FORMA_PAGAMENTO_INVALIDA);
84	        }
85	        FormaPagamento formaPagamento = pagamentoRegistry.buscar(req.formaPagamento());
86	
87	        // 9. Validate parcelas
88	        int parcelas = req.parcelas() != null ? req.parcelas() : 1;
89	        formaPagamento.validarParcelas(parcelas);
90	
91	        // Calculate frete
92	        BigDecimal frete = modalidade.calcularFrete(pesoTotal);
93	        if (nivelClube.isFreteGratis()) {
94	            frete = BigDecimal.ZERO.setScale(2);
95	        }
96	
97	        // Calculate cupom desconto
98	        BigDecimal descontoCupom = BigDecimal.ZERO.setScale(2);
99	        if (cupom != null) {
100	            descontoCupom = cupom.calcularDesconto(subtotalProdutos, frete, req.itens());
101	        }
102	
103	        // Calculate seguro (sobre subtotalProdutos, sem desconto e sem frete)
104	        BigDecimal seguro = regiao.calcularSeguro(subtotalProdutos);
105	
106	        // Total do pedido
107	        BigDecimal totalPedido = subtotalProdutos
108	                .subtract(descontoCupom)
109	                .add(frete)
110	                .add(seguro);
111	
112	        // 10. Validate forma pagamento disponibilidade
113	        formaPagamento.validarDisponibilidade(totalPedido);
114	
115	        // Calculate total final and parcela
116	        BigDecimal totalFinal = formaPagamento.calcularTotalFinal(totalPedido, parcelas);
117	        BigDecimal valorParcela = formaPagamento.calcularParcela(totalFinal, parcelas);
118	        BigDecimal ajustePagamento = totalFinal.subtract(totalPedido);
119	
120	        // Club benefits
121	        BigDecimal credito = nivelClube.calcularCredito(subtotalProdutos);
122	        boolean brinde = nivelClube.ganharBrinde(subtotalProdutos);
123	
124	        return new ResumoResponse(
125	                subtotalProdutos,
126	                descontoCupom,
127	                frete,
128	                modalidade.getPrazo(),
129	                seguro,
130	                ajustePagamento,
131	                totalFinal,
132	                parcelas,
133	                valorParcela,
134	                credito,
135	                brinde
136	        );
137	    }
138	
139	    private void validarItens(List<ItemCarrinho> itens) {
140	        if (itens == null || itens.isEmpty()) {
141	            throw new CheckoutException(ErroCodigo.PEDIDO_INVALIDO);
142	        }
143	        for (ItemCarrinho item : itens) {
144	            if (item.precoUnitario() == null
145	                    || item.precoUnitario().compareTo(BigDecimal.ZERO) <= 0
146	                    || item.quantidade() == null
147	                    || item.quantidade() <= 0
148	                    || item.pesoKg() == null
149	                    || item.pesoKg() <= 0) {
150	                throw new CheckoutException(ErroCodigo.PEDIDO_INVALIDO);
151	            }
152	        }
153	    }
154	
155	    private SeguroRegiao resolveRegiao(String codigo) {
156	        if (codigo == null) {
157	            throw new CheckoutException(ErroCodigo.REGIAO_INVALIDA);
158	        }
159	        try {
160	            return SeguroRegiao.valueOf(codigo);
161	        } catch (IllegalArgumentException e) {
162	            throw new CheckoutException(ErroCodigo.REGIAO_INVALIDA);
163	        }
164	    }
165	
166	    private double calcularPesoTotal(List<ItemCarrinho> itens) {
167	        double peso = 0.0;
168	        for (ItemCarrinho item : itens) {
169	            peso += item.pesoKg() * item.quantidade();
170	        }
171	        return peso;
172	    }
173	
174	    private BigDecimal calcularSubtotal(List<ItemCarrinho> itens) {
175	        BigDecimal subtotal = BigDecimal.ZERO;
176	        for (ItemCarrinho item : itens) {
177	            subtotal = subtotal.add(
178	                    item.precoUnitario().multiply(BigDecimal.valueOf(item.quantidade()))
179	            );
180	        }
181	        return subtotal.setScale(2, RoundingMode.HALF_EVEN);
182	    }
183	}
