1	package com.loja.checkout.pagamento;
2	
3	import com.loja.checkout.exception.CheckoutException;
4	import com.loja.checkout.exception.ErroCodigo;
5	
6	import java.math.BigDecimal;
7	import java.math.RoundingMode;
8	
9	public class PagamentoCartao implements FormaPagamento {
10	
11	    private static final int MAX_PARCELAS = 12;
12	    private static final int MAX_SEM_JUROS = 3;
13	    private static final double TAXA_MENSAL = 0.0199;
14	
15	    @Override
16	    public void validarParcelas(int parcelas) {
17	        if (parcelas < 1 || parcelas > MAX_PARCELAS) {
18	            throw new CheckoutException(ErroCodigo.PARCELAMENTO_INVALIDO);
19	        }
20	    }
21	
22	    @Override
23	    public void validarDisponibilidade(BigDecimal totalPedido) {
24	    }
25	
26	    @Override
27	    public BigDecimal calcularTotalFinal(BigDecimal totalPedido, int parcelas) {
28	        if (parcelas <= MAX_SEM_JUROS) {
29	            return totalPedido;
30	        }
31	        BigDecimal parcela = calcularParcelaComJuros(totalPedido, parcelas);
32	        return parcela.multiply(BigDecimal.valueOf(parcelas));
33	    }
34	
35	    @Override
36	    public BigDecimal calcularParcela(BigDecimal totalFinal, int parcelas) {
37	        return totalFinal.divide(BigDecimal.valueOf(parcelas), 2, RoundingMode.HALF_EVEN);
38	    }
39	
40	    private BigDecimal calcularParcelaComJuros(BigDecimal total, int n) {
41	        double pow = Math.pow(1.0 + TAXA_MENSAL, -n);
42	        double parcela = total.doubleValue() * TAXA_MENSAL / (1.0 - pow);
43	        return BigDecimal.valueOf(parcela).setScale(2, RoundingMode.HALF_EVEN);
44	    }
45	}
