        mockMvc = MockMvcBuilders.webAppContextSetup(wac).build();
    }

    // Exemplo 1: Camiseta 79.90×2 + Tênis 249.90×1, EXPRESSA, BEMVINDO10, PIX, BRONZE, NORTE
